use crate::sweep_gga::GgaChunk;

/// Output fields a GGA evaluation of `order` must be given.
fn required_fields(order: DerivativeOrder) -> &'static [&'static str] {
    match order {
        DerivativeOrder::Exc => &["zk"],
        DerivativeOrder::Vxc => &["zk", "vrho", "vsigma"],
        DerivativeOrder::Fxc => &["zk", "vrho", "vsigma", "v2rho2", "v2rhosigma", "v2sigma2"],
        DerivativeOrder::Kxc => &["zk", "vrho", "vsigma", "v2rho2", "v2rhosigma", "v2sigma2", "v3rho3", "v3rho2sigma", "v3rhosigma2", "v3sigma3"],
        DerivativeOrder::Lxc => &["zk", "vrho", "vsigma", "v2rho2", "v2rhosigma", "v2sigma2", "v3rho3", "v3rho2sigma", "v3rhosigma2", "v3sigma3", "v4rho4", "v4rho3sigma", "v4rho2sigma2", "v4rhosigma3", "v4sigma4"],
    }
}

/// Validate the caller's buffers and build the chunk view.
///
/// Kernels accumulate with `+=`, so every destination must start at zero --
/// but that zeroing happens per chunk inside `par_sweep`, not here. See the
/// comment on `zero_outputs` for why. Buffers the caller supplied for an order
/// higher than the one requested are still cleared here: they are dropped from
/// the chunk, so the sweep never sees them, and leaving stale values in a
/// buffer the caller handed us would be worse than the cost of clearing it.
pub fn prepare<'inp, 'out>(
    input: &GgaInput<'inp>,
    output: &mut GgaOutput<'out>,
    order: DerivativeOrder,
    d: &Dimensions,
) -> Result<GgaChunk<'inp, 'out>, LibxcRsError> {
    let np = input.np();
    let need = required_fields(order);

    macro_rules! take {
        ($f:ident, $name:literal, $stride:expr) => {{
            let wanted = need.contains(&$name);
            match output.$f.take() {
                Some(b) if wanted => {
                    let expected = np * $stride as usize;
                    if b.len() != expected {
                        return Err(LibxcRsError::OutputBufferSizeMismatch {
                            field: $name, expected, actual: b.len(),
                        });
                    }
                    Some(b)
                }
                Some(b) => { b.fill(0.0); None }
                None if wanted => {
                    return Err(LibxcRsError::OutputBufferSizeMismatch {
                        field: $name, expected: np * $stride as usize, actual: 0,
                    })
                }
                None => None,
            }
        }};
    }

    Ok(GgaChunk {
        np,
        rho: input.rho(),
        sigma: input.sigma(),
        zk: take!(zk, "zk", d.zk),
        vrho: take!(vrho, "vrho", d.vrho),
        vsigma: take!(vsigma, "vsigma", d.vsigma),
        v2rho2: take!(v2rho2, "v2rho2", d.v2rho2),
        v2rhosigma: take!(v2rhosigma, "v2rhosigma", d.v2rhosigma),
        v2sigma2: take!(v2sigma2, "v2sigma2", d.v2sigma2),
        v3rho3: take!(v3rho3, "v3rho3", d.v3rho3),
        v3rho2sigma: take!(v3rho2sigma, "v3rho2sigma", d.v3rho2sigma),
        v3rhosigma2: take!(v3rhosigma2, "v3rhosigma2", d.v3rhosigma2),
        v3sigma3: take!(v3sigma3, "v3sigma3", d.v3sigma3),
        v4rho4: take!(v4rho4, "v4rho4", d.v4rho4),
        v4rho3sigma: take!(v4rho3sigma, "v4rho3sigma", d.v4rho3sigma),
        v4rho2sigma2: take!(v4rho2sigma2, "v4rho2sigma2", d.v4rho2sigma2),
        v4rhosigma3: take!(v4rhosigma3, "v4rhosigma3", d.v4rhosigma3),
        v4sigma4: take!(v4sigma4, "v4sigma4", d.v4sigma4),
    })
}

